-- 0004_site_templates.sql: Platform site template library and site template_id tracking (Swarm T)

CREATE TABLE IF NOT EXISTS site_templates (
    id TEXT PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    archetype TEXT NOT NULL,
    description TEXT NOT NULL,
    preview_image_url TEXT NOT NULL DEFAULT '',
    tags TEXT[] NOT NULL DEFAULT '{}',
    config JSONB NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_site_templates_active_sort
    ON site_templates (is_active, sort_order ASC, id ASC);

ALTER TABLE sites ADD COLUMN IF NOT EXISTS template_id TEXT NULL;

INSERT INTO site_templates (
    id, slug, name, category, archetype, description, preview_image_url, tags, config, is_active, sort_order
) VALUES (
    'minimal-fashion', 'minimal-fashion', 'Thời Trang Tối Giản', 'fashion', 'minimal-fashion', 'Bố cục nhiều khoảng thở, lưới 3 cột sắc nét và lookbook nổi bật dành cho thương hiệu thời trang đương đại.', '/banners/campaign-everyday.jpg', ARRAY['minimal', 'fashion', 'lookbook', 'clean']::text[], $cfg${"schema_version":2,"template_id":"minimal-fashion","theme":{"bg_color":"#FAFAFA","surface_color":"#FFFFFF","text_color":"#111827","accent_color":"#111827","accent_text_color":"#FFFFFF","font_family":"inter","logo_url":"/banners/vietnam-workshop.jpg","banner_url":"/banners/campaign-everyday.jpg","brand_name":"Studio Tối Giản","tagline":"Phom dáng tinh gọn và chất liệu tự nhiên cho tủ đồ mặc mỗi ngày","radius":"none","density":"airy"},"layout":{"archetype":"minimal-fashion","header_style":"minimal-split","footer_style":"minimal-row","container_width":"standard","card_style":"minimal","show_announcement":false,"announcement_text":"","slots":{"search":true,"chat":true,"assistant":true}},"sections":[{"id":"mf-hero","type":"hero","visible":true,"variant":"minimal","settings":{"surface":"bg","padding":"generous","align":"left"},"props":{"eyebrow":"BỘ SƯU TẬP MỚI","title":"Đường cắt tối giản, mặc bền qua nhiều mùa","subtitle":"Thiết kế trung tính tập trung vào chất vải tự nhiên và độ rủ chuẩn xác cho nhịp sống đô thị.","image_url":"/banners/campaign-everyday.jpg","cta_label":"Khám phá ngay","cta_href":"/san-pham"},"blocks":[{"id":"mf-h-b1","type":"badge","props":{"label":"Cotton chải kỹ","tone":"outline"}},{"id":"mf-h-b2","type":"cta","props":{"label":"Xem câu chuyện","href":"/gioi-thieu","style":"link"}}]},{"id":"mf-lookbook","type":"lookbook","visible":true,"variant":"editorial-grid","settings":{"surface":"surface","padding":"generous","columns":3},"props":{"title":"Lookbook mặc hằng ngày","subtitle":"Ba bản phối dễ ứng dụng từ phòng làm việc đến cuối tuần.","cta_label":"Xem toàn bộ danh mục","cta_href":"/san-pham"},"blocks":[{"id":"mf-lb-1","type":"image","props":{"image_ur