INSERT INTO site_templates (
    id, slug, name, category, archetype, description, preview_image_url, tags, config, is_active, sort_order
) VALUES (
    'editorial', 'editorial', 'Tạp Chí Editorial', 'editorial', 'editorial', 'Nhịp điệu kể chuyện như tạp chí thời trang với tiêu đề giữa, khối trích dẫn, mosaic ảnh và trang giới thiệu dạng bài luận.', '/banners/campaign-office.jpg', ARRAY['editorial', 'magazine', 'storytelling', 'lookbook']::text[], $cfg${"schema_version":2,"template_id":"editorial","theme":{"bg_color":"#F6F1E9","surface_color":"#FFFDF9","text_color":"#1F1A17","accent_color":"#9A3412","accent_text_color":"#FFFFFF","font_family":"plus-jakarta-sans","logo_url":"/banners/campaign-office.jpg","banner_url":"/banners/campaign-office.jpg","brand_name":"Tạp Chí Sợi Việt","tagline":"Chuyện nghề dệt may, chất liệu bản địa và nhịp mặc chậm có chủ đích","radius":"sm","density":"airy"},"layout":{"archetype":"editorial","header_style":"centered-masthead","footer_style":"editorial-cols","container_width":"narrow","card_style":"editorial","show_announcement":true,"announcement_text":"Ấn phẩm Thu — Đông: Khám phá bộ sưu tập sợi tự nhiên dệt tại Việt Nam","slots":{"search":true,"chat":true,"assistant":true}},"sections":[{"id":"ed-hero","type":"hero","visible":true,"variant":"editorial","settings":{"surface":"bg","padding":"generous","align":"center"},"props":{"eyebrow":"SỐ ĐẶC BIỆT","title":"Từ sợi bông nguyên bản đến phom áo vượt thời gian","subtitle":"Một hành trình nhìn gần hơn vào chất liệu, màu nhuộm trầm ấm và những người thợ đứng sau từng đường kim.","image_url":"/banners/campaign-office.jpg","cta_label":"Đọc \u0026 Mua sắm","cta_href":"/san-pham"},"blocks":[{"id":"ed-h-b1","type":"badge","props":{"label":"Ấn phẩm 04","tone":"accent"}},{"id":"ed-h-b2","type":"cta","props":{"label":"Câu chuyện xưởng","href":"/gioi-thieu","style":"outline"}}]},{"id":"ed-story","type":"text","visible":true,"variant":"editorial","settings":{"surface":"surface","padding":"generous","align":"left"},"props":{"title":"Mặc ít hơn, chọn kỹ hơn","body":"Chúng tôi thiết kế mỗi bộ sưu tập như một chương truyện nối tiếp thay vì chạy theo chu kỳ giảm giá ngắn hạn. Từng chất liệu được thử nghiệm trực tiếp trong khí hậu nhiệt đới để giữ độ thoáng và bền màu theo năm tháng.","align":"left"},"blocks":[{"id":"ed-st-1","type":"heading","props":{"text":"Ghi chép từ phòng rập","level":3}},{"id":"ed-st-2","type":"paragraph","props":{"text":"Mỗi mẫu rập đi qua ít nhất 3 vòng mặc thử trước khi đưa lên dây chuyền cắt chính thức."}},{"id":"ed-st-3","type":"quote","props":{"body":"Trang phục tốt không phô trương, nó đồng hành lặng lẽ suốt cả ngày dài.","author":"Minh Khuê","role":"Giám đốc thiết kế"}}]},{"id":"ed-lookbook","type":"lookbook","visible":true,"variant":"mosaic","settings":{"surface":"bg","padding":"generous","columns":3},"props":{"title":"Khung hình chất liệu","subtitle":"Ánh sáng tự nhiên tôn lên kết cấu dệt mộc mạc của từng sản phẩm.","cta_label":"Khám phá danh mục","cta_href":"/san-pham"},"blocks":[{"id":"ed-lb-1","type":"image","props":{"image_url":"/atmosphere/cotton-boll-harvest.jpg","alt":"Bông tự nhiên thu hoạch","caption":"Chương I — Nguyên liệu thuần khiết","aspect":"landscape"}},{"id":"ed-lb-2","type":"image","props":{"image_url":"/banners/vietnam-workshop.jpg","alt":"Xưởng may tại Việt Nam","caption":"Chương II — Bàn tay người thợ","aspect":"portrait"}},{"id":"ed-lb-3","type":"image","props":{"image_url":"/banners/campaign-green-fiber.jpg","alt":"Trang phục sợi thực vật","caption":"Chương III — Nhịp mặc hàng ngày","aspect":"square"}}]},{"id":"ed-featured","type":"featured_products","visible":true,"variant":"editorial","settings":{"surface":"surface","padding":"normal","columns":2,"max_items":4},"props":{"title":"Tuyển chọn của biên tập viên","subtitle":"Bốn thiết kế đại diện cho tinh thần bộ sưu tập mùa này.","product_ids":[],"limit":4}},{"id":"ed-testimonials","type":"testimonials","visible":true,"variant":"editorial-quotes","settings":{"surface":"band","padding":"normal","columns":2},"props":{"title":"Cảm nhận từ người mặc","subtitle":"Những chia sẻ thực tế sau nhiều tháng đồng hành cùng sản phẩm."},"blocks":[{"id":"ed-q1","type":"quote","props":{"body":"Vải mặc rất mát, giặt máy nhiều lần cổ áo vẫn phẳng và không bị chảy phom.","author":"Thu Hà","role":"Kiến trúc sư, TP.HCM"}},{"id":"ed-q2","type":"quote","props":{"body":"Tông màu trầm ấm dễ phối đồ, giao hàng chỉn chu từ hộp đến giấy gói.","author":"Quang Huy","role":"Nhiếp ảnh gia, Hà Nội"}}]},{"id":"ed-vouchers","type":"voucher_strip","visible":true,"variant":"minimal","settings":{"surface":"bg","padding":"compact"},"props":{"title":"Đặc quyền dành cho độc giả","subtitle":"Lưu mã ưu đãi của gian hàng trước khi hoàn tất đơn.","limit":3}}],"pages":{"catalog":{"layout":"editorial-magazine","columns":2,"show_filters":true,"show_search":true,"show_sku_matrix":false,"intro_title":"Danh mục tuyển chọn","intro_subtitle":"Trình bày khổ lớn 2 cột giúp quan sát rõ phom dáng và chất liệu từng thiết kế.","sections":[{"id":"ed-cat-banner","type":"banner","visible":true,"variant":"framed","props":{"title":"Cần tư vấn phối đồ theo vóc dáng?","subtitle":"Nhắn trực tiếp cho đội ngũ tư vấn ngay trên cửa hàng để chọn đúng kích cỡ.","image_url":"/banners/fabric-closeup.jpg","cta_label":"Xem hướng dẫn","cta_href":"/gioi-thieu"}}]},"pdp":{"layout":"editorial-tall","gallery_style":"stacked","show_vouchers":true,"show_sku_table":false,"show_story_band":true,"show_related":true},"cart":{"layout":"editorial-ledger","show_vouchers":true,"show_addons":true,"trust_note":"Mỗi đơn hàng được kiểm tra thủ công trước khi rời xưởng."},"info":{"layout":"editorial-essay","show_factory_profile":true,"show_toc":true,"show_showcase":true,"sections":[{"id":"ed-info-quotes","type":"testimonials","visible":true,"variant":"editorial-quotes","props":{"title":"Dấu ấn cộng đồng","subtitle":"Phản hồi từ khách hàng đã ghé thăm và trải nghiệm."},"blocks":[{"id":"ed-iq-1","type":"quote","props":{"body":"Đọc câu chuyện xưởng xong mới hiểu vì sao đường may phẳng và mịn đến vậy.","author":"Ngọc Anh","role":"Khách hàng thân thiết"}}]}]}}}$cfg$::json