elated":true},"cart":{"layout":"compact-table","show_vouchers":true,"show_addons":true,"trust_note":"Giá hiển thị đã bao gồm kiểm tra chất lượng và đóng gói chống ẩm."},"info":{"layout":"compact-faq","show_factory_profile":false,"show_toc":true,"show_showcase":false,"sections":[{"id":"dg-info-faq","type":"policies","visible":true,"variant":"list","props":{"title":"Câu hỏi thường gặp","items":[{"heading":"Bao lâu nhận được hàng?","detail":"Nội thành 2–4 giờ, liên tỉnh 1–3 ngày làm việc."},{"heading":"Đổi size có mất phí không?","detail":"Miễn phí đổi size lần đầu cho mọi đơn hàng đủ điều kiện."}]}}]}}}$cfg$::jsonb, TRUE, 3
) ON CONFLICT (id) DO NOTHING;

INSERT INTO site_templates (
    id, slug, name, category, archetype, description, preview_image_url, tags, config, is_active, sort_order
) VALUES (
    'craft-atelier', 'craft-atelier', 'Xưởng Thủ Công', 'craft', 'craft-atelier', 'Tôn vinh quy trình sản xuất bản địa, chỉ số kiểm định chất liệu, dòng thời gian xưởng nghề và tông màu sợi tự nhiên ấm áp.', '/banners/vietnam-workshop.jpg', ARRAY['craft', 'atelier', 'workshop', 'sustainable']::text[], $cfg${"schema_version":2,"template_id":"craft-atelier","theme":{"bg_color":"#EFF2EA","surface_color":"#FBFDF8","text_color":"#1B261E","accent_color":"#2E5A3C","accent_text_color":"#FFFFFF","font_family":"ibm-plex-sans","logo_url":"/banners/vietnam-workshop.jpg","banner_url":"/banners/campaign-green-fiber.jpg","brand_name":"Xưởng Dệt Thủ Công","tagline":"Dệt may minh bạch nguồn sợi, kiểm định 3 bước trực tiếp tại xưởng Việt","radius":"md","density":"balanced"},"layout":{"archetype":"craft-atelier","header_style":"atelier-framed","footer_style":"atelier-footer","container_width":"standard","card_style":"atelier","show_announcement":true,"announcement_text":"Giá trực tiếp từ xưởng • Minh bạch định lượng sợi và lô sản xuất","slots":{"search":true,"chat":true,"assistant":true}},"sections":[{"id":"ca-hero","type":"hero","visible":true,"variant":"framed","settings":{"surface":"bg","padding":"generous","align":"left"},"props":{"eyebrow":"XƯỞNG MAY BẢN ĐỊA","title":"Từng đường kim kiểm định trước khi đóng gói","subtitle":"Chủ động từ chọn sợi thực vật, dệt kim tròn đến giặt enzyme xử lý co rút ngay tại xưởng nội địa.","image_url":"/banners/vietnam-workshop.jpg","cta_label":"Xem sản phẩm xưởng","cta_href":"/san-pham"},"blocks":[{"id":"ca-h-1","type":"badge","props":{"label":"Trực tiếp từ xưởng","tone":"accent"}},{"id":"ca-h-2","type":"feature","props":{"title":"Giặt enzyme sinh học","detail":"Chạm dịu ngay từ lần mặc đầu tiên, hạn chế co rút dưới 2%.","tag":"Bước 02"}}]},{"id":"ca-metrics","type":"metrics_strip","visible":true,"variant":"cards","settings":{"surface":"surface","padding":"normal","columns":3},"props":{"title":"Hồ sơ kỹ thuật xưởng","subtitle":"Các chỉ tiêu đo kiểm áp dụng trên 100% lô vải trước khi xuất xưởng."},"blocks":[{"id":"ca-m1","type":"stat","props":{"value":"220 gsm","label":"Định lượng vải chuẩn","note":"Đứng phom nhưng vẫn thoáng khí"}},{"id":"ca-m2","type":"stat","props":{"value":"3 bước","label":"Kiểm định QC","note":"Đo co rút, mật độ mũi kim, bền màu"}},{"id":"ca-m3","type":"stat","props":{"value":"45 ngày","label":"Bảo hành đổi cỡ","note":"Hỗ trợ tận nơi hai chiều"}}]},{"id":"ca-collection","type":"collection","visible":true,"variant":"split","settings":{"surface":"band","padding":"normal","columns":3},"props":{"title":"Dòng sợi thực vật thoáng nhẹ","subtitle":"Lanh pha bông, sợi tre thiên nhiên và cotton pique chải kỹ.","collection_slug":"natural-fibers","category_slug":"ao-polo","image_url":"/banners/campaign-green-fiber.jpg","limit":6}},{"id":"ca-craft-notes","type":"text","visible":true,"variant":"framed","settings":{"surface":"surface","padding":"normal","align":"left"},"props":{"title":"Quy trình làm ra một chiếc áo tại xưởng","body":"Mỗi công đoạn từ dệt mộc, nhuộm hoàn tất đến cắt rập và may chập phẳng đều được ghi nhận theo mã lô. Khách hàng luôn biết rõ thành phần sợi, định lượng và hướng dẫn bảo quản đi kèm.","align":"left"},"blocks":[{"id":"ca-f1","type":"feature","props":{"title":"Chọn sợi chải kỹ","detail":"Loại bỏ xơ ngắn giúp bề mặt vải mịn và hạn chế xù lông.","tag":"01"}},{"id":"ca-f2","type":"feature","props":{"title":"Cắt rập chuẩn dáng Việt","detail":"Cân chỉnh độ xuôi vai và vòng nách cho cảm giác cử động thoải mái.","tag":"02"}},{"id":"ca-f3","type":"feature","props":{"title":"Soi bàn sáng từng chiếc","detail":"Kiểm tra đường may cổ áo, gấu áo và nẹp trước khi gấp hộp.","tag":"03"}}]},{"id":"ca-featured","type":"featured_products","visible":true,"variant":"grid","settings":{"surface":"bg","padding":"normal","columns":3,"max_items":6},"props":{"title":"Sản phẩm chủ lực của xưởng","subtitle":"Các thiết kế được hoàn thiện trực tiếp và luôn giữ ổn định chất lượng qua từng đợt.","product_ids":[],"limit":6}},{"id":"ca-testimonials","type":"testimonials","visible":true,"variant":"cards","settings":{"surface":"surface","padding":"normal","columns":2},"props":{"title":"Đánh giá từ khách mặc lâu năm","subtitle":"Trải nghiệm thực tế về độ bền phom và cảm giác chất liệu."},"blocks":[{"id":"ca-q1","type":"quote","props":{"body":"Áo polo pique cổ đứng rất đẹp, mặc đi làm cả ngày mùa hè vẫn dễ chịu.","author":"Hoàng Minh","role":"Đà Nẵng"}},{"id":"ca-q2","type":"quote","props":{"body":"Thích cách xưởng ghi rõ định lượng gsm và chăm chút từng đường may phẳng.","author":"Bảo Trâm","role":"Hải Phòng"}}]},{"id":"ca-policies","type":"policies","visible":true,"variant":"timeline","settings":{"surface":"bg","padding":"normal","columns":3},"props":{"title":"Cam kết hậu mãi tại xưởng","items":[{"heading":"Nguồn sợi truy xuất","detail":"Công bố rõ tỷ lệ sợi, định lượng và hướng dẫn giặt ủi trên nhãn."},{"heading":"Đổi size tận nhà 45 ngày","detail":"Bưu tá nhận lại và giao size mới trong một lượt."},{"heading":"Sửa chữa nhỏ miễn phí","detail":"Hỗ trợ gia cố đường chỉ cho sản phẩm mua tại gian hàng."}]}}],"pages":{"catalog":{"layout":"top-bar","columns":3,"show_filters":true,"show_search":true,"show_sku_matrix":false,"intro_title":"Sản phẩm từ xưởng","intro_subtitle":"Chọn lọc theo dòng chất liệu và nhu cầu sử dụng hằng ngày.","sections":[{"id":"ca-cat-metrics","type":"metrics_strip","visible":true,"variant":"inline-bar","props":{"title":"Minh bạch xuất xưởng","subtitle":"Mọi sản phẩm trên gian hàng đều sản xuất trực tiếp không qua trung gian."},"blocks":[{"id":"ca-cm1","type":"stat","props":{"value":"100%","label":"Sản xuất nội địa","note":"Kiểm định từng lô"}},{"id":"ca-cm2","type":"stat","props":{"value":"\u003c 2%","label":"Độ co rút tối đa","note":"Đã qua giặt thử"}}]}]},"pdp":{"layout":"atelier-story","gallery_style":"framed","show_vouchers":true,"show_sku_table":false,"show_story_band":true,"show_related":true},"cart":{"layout":"atelier-bag","show_vouchers":true,"show_addons":true,"trust_note":"Đóng gói trực tiếp tại xưởng cùng thẻ hướng dẫn chăm sóc chất liệu."},"info":{"layout":"craft-timeline","show_factory_profile":true,"show_toc":true,"show_showcase":true,"sections":[{"id":"ca-info-story","type":"text","visible":true,"variant":"framed","props":{"title":"Dấu mốc hình thành xưởng","body":"Khởi đầu từ một chuyền dệt gia đình, chúng tôi nâng cấp dần hệ thống máy dệt tròn, bàn cắt chuẩn và phòng kiểm định chất liệu để giữ chất lượng ổn định quanh năm.","align":"left"}}]}}}$cfg$::jsonb, TRUE, 4
) ON CONFLICT (id) DO NOTHING;

INSERT INTO site_templates (
    id, slug, name, category, archetype, description, preview_image_url, tags, config, is_active, sort_order
) VALUES (
    'sport-active', 'sport-active', 'Thể Thao Năng Động', 'sport', 'sport-active', 'Nền tối tương phản cao, dải thông số hiệu năng (telemetry), ảnh hành động toàn chiều rộng và luồng thanh toán nhanh.', '/banners/campaign-running.jpg', ARRAY['sport', 'dark', 'activewear', 'telemetry']::text[], $cfg${"schema_version":2,"template_id":"sport-active","theme":{"bg_color":"#11151A","surface_color":"#1B222A","text_color":"#F8FAFC","accent_color":"#F59E0B","accent_text_color":"#11151A","font_family":"be-vietnam-pro","logo_url":"/banners/campaign-running.jpg","banner_url":"/banners/campaign-running.jpg","brand_name":"Đường Chạy Việt","tagline":"Trang phục vận động siêu nhẹ, thoát ẩm nhanh cho thời tiết nhiệt đới","radius":"sm","density":"balanced"},"layout":{"archetype":"sport-active","header_style":"bold-dark","footer_style":"bold-dark","container_width":"wide","card_style":"sport","show_announcement":true,"announcement_text":"DRY-FIT 145GSM • Giao hỏa tốc 2–4 giờ nội thành • Đổi size miễn phí","slots":{"search":true,"chat":true,"assistant":true}},"sections":[{"id":"sp-hero","type":"hero","visible":true,"variant":"bold-sport","settings":{"surface":"bg","padding":"generous","align":"left"},"props":{"eyebrow":"HIỆU NĂNG VẬN ĐỘNG","title":"Nhẹ từng bước chạy, khô thoáng suốt cung đường","subtitle":"Sợi Micro-mesh tái chế kết hợp đường may chập phẳng 4 kim 6 chỉ giúp giảm tối đa ma sát khi tập cường độ cao.","image_url":"/banners/campaign-running.jpg","cta_label":"Mua đồ tập ngay","cta_href":"/san-pham"},"blocks":[{"id":"sp-h-b1","type":"badge","props":{"label":"Dry-Fit 145gsm","tone":"accent"}},{"id":"sp-h-s1","type":"stat","props":{"value":"45 phút","label":"Khô nhanh phơi gió","note":"Thử nghiệm độ ẩm thực tế"}}]},{"id":"sp-telemetry","type":"metrics_strip","visible":true,"variant":"telemetry","settings":{"surface":"surface","padding":"normal","columns":4},"props":{"title":"Thông số hiệu năng chất liệu","subtitle":"Đo kiểm trên từng lô vải thể thao trước khi cắt may."},"blocks":[{"id":"sp-t1","type":"stat","props":{"value":"145 gsm","label":"Trọng lượng siêu nhẹ","note":"Không bám dính mồ hôi"}},{"id":"sp-t2","type":"stat","props":{"value":"4 chiều","label":"Độ đàn hồi","note":"Cử động tự do mọi góc"}},{"id":"sp-t3","type":"stat","props":{"value":"4K6C","label":"May chập phẳng","note":"Hạn chế cọ xát vùng nách"}},{"id":"sp-t4","type":"stat","props":{"value":"UPF 40+","label":"Chống nắng nhẹ","note":"Phù hợp chạy ngoài trời"}}]},{"id":"sp-featured","type":"featured_products","visible":true,"variant":"spotlight","settings":{"surface":"bg","padding":"normal","columns":4,"max_items":8},"props":{"title":"Trang bị bán chạy cho Runner \u0026 Gym","subtitle":"Tối ưu từ buổi chạy 5K sáng sớm tới các buổi tập dài cuối tuần.","product_ids":[],"limit":8}},{"id":"sp-banner","type":"banner","visible":true,"variant":"full-bleed","settings":{"surface":"band","padding":"normal"},"props":{"title":"Short chạy bộ 5 inch có túi khóa kéo sau lưng","subtitle":"Giữ chắc điện thoại, gel năng lượng và chìa khóa mà không rung lắc.","image_url":"/banners/campaign-green-fiber.jpg","cta_label":"Xem quần short","cta_href":"/san-pham?category=quan-short"}},{"id":"sp-lookbook","type":"lookbook","visible":true,"variant":"horizontal-film","settings":{"surface":"surface","padding":"normal","columns":3},"props":{"title":"Trên đường chạy thực tế","subtitle":"Thử nghiệm cùng các câu lạc bộ chạy bộ nội địa.","cta_label":"Xem bộ sưu tập","cta_href":"/san-pham"},"blocks":[{"id":"sp-lb1","type":"image","props":{"image_url":"/banners/campaign-running.jpg","alt":"Chạy bộ sáng sớm","caption":"Tempo Run — Áo Dry-Fit thoáng khí","aspect":"wide"}},{"id":"sp-lb2","type":"image","props":{"image_url":"/banners/campaign-green-fiber.jpg","alt":"Chất liệu tái chế","caption":"Sợi Micro-mesh nhẹ mát","aspect":"wide"}},{"id":"sp-lb3","type":"image","props":{"image_url":"/atmosphere/cotton-twill-slate.jpg","alt":"Phục hồi sau buổi tập","caption":"Đồ mặc thư giãn sau tập","aspect":"wide"}}]},{"id":"sp-vouchers","type":"voucher_strip","visible":true,"variant":"tickets","settings":{"surface":"bg","padding":"compact"},"props":{"title":"Mã ưu đãi cho đội nhóm \u0026 cá nhân","subtitle":"Lưu mã trước khi thanh toán để nhận chiết khấu trực tiếp.","limit":4}},{"id":"sp-policies","type":"policies","visible":true,"variant":"grid","settings":{"surface":"surface","padding":"compact","columns":3},"props":{"title":"Hỗ trợ vận động viên","items":[{"heading":"Giao nhanh 2–4 giờ","detail":"Đáp ứng kịp lịch tập và giải chạy cuối tuần tại nội thành."},{"heading":"Đổi size không rườm rà","detail":"Hỗ trợ đổi form ôm hay rộng trong vòng 45 ngày."},{"heading":"Tư vấn chọn cỡ nhanh","detail":"Đội ngũ phản hồi theo chiều cao, cân nặng và thói quen vận động."}]}}],"pages":{"catalog":{"layout":"top-bar","columns":4,"show_filters":true,"show_search":true,"show_sku_matrix":false,"intro_title":"Trang bị thể thao","intro_subtitle":"Lọc nhanh theo dòng vận động, chất liệu và tầm giá."},"pdp":{"layout":"sport-telemetry","gallery_style":"thumbnails","show_vouchers":true,"show_sku_table":false,"show_story_band":true,"show_related":true},"cart":{"layout":"express-bar","show_vouchers":true,"show_addons":true,"trust_note":"Đóng gói chống ẩm và xuất kho ngay trong ngày cho đơn trước 17:00."},"info":{"layout":"athletic-manifesto","show_factory_profile":true,"show_toc":false,"show_showcase":true,"sections":[{"id":"sp-info-metrics","type":"metrics_strip","visible":true,"variant":"telemetry","props":{"title":"Kiểm thử thực địa","subtitle":"Mỗi mẫu áo chạy đều vượt qua 200 km chạy thử trước khi ra mắt."},"blocks":[{"id":"sp-im1","type":"stat","props":{"value":"200+ km","label":"Chạy thử nghiệm","note":"Đánh giá độ bền đường may"}},{"id":"sp-im2","type":"stat","props":{"value":"35°C","label":"Kiểm thử nhiệt ẩm","note":"Tối ưu cho khí hậu Việt Nam"}}]}]}}}$cfg$::jsonb, TRUE, 5
) ON CONFLICT (id) DO NOTHING;

INSERT INTO site_templates (
    id, slug, name, category, archetype, description, preview_image_url, tags, config, is_active, sort_order
) VALUES (
    'luxury-maison', 'luxury-maison', 'Cao Cấp Maison', 'luxury', 'luxury-maison', 'Không gian tối sang trọng với điểm nhấn vàng ánh kim, khung ảnh lookbook rộng rãi và danh mục tuyển chọn 2 cột.', '/atmosphere/jacquard-loom-poster.jpg', ARRAY['luxury', 'maison', 'dark', 'curated']::text[], $cfg${"schema_version":2,"template_id":"luxury-maison","theme":{"bg_color":"#1D1417","surface_color":"#291D21","text_color":"#F9F2EC","accent_color":"#E6B85C","accent_text_color":"#1D1417","font_family":"plus-jakarta-sans","logo_url":"/atmosphere/cotton-twill-slate.jpg","banner_url":"/atmosphere/jacquard-loom-poster.jpg","brand_name":"Maison Dệt Kim","tagline":"Tay nghề dệt kim tinh tuyển, số lượng giới hạn cho từng mùa","radius":"none","density":"airy"},"layout":{"archetype":"luxury-maison","header_style":"maison-centered","footer_style":"maison-minimal","container_width":"narrow","card_style":"luxury","show_announcement":false,"announcement_text":"","slots":{"search":true,"chat":true,"assistant":true}},"sections":[{"id":"lm-hero","type":"hero","visible":true,"variant":"luxury-maison","settings":{"surface":"bg","padding":"generous","align":"center"},"props":{"eyebrow":"MAISON ARCHIVE","title":"Nghệ thuật dệt kim trầm mặc và chuẩn xác","subtitle":"Mỗi thiết kế được dệt tỉ mỉ từ sợi cotton dài và nỉ chân cua 320gsm, giữ phom sang trọng qua nhiều năm.","image_url":"/atmosphere/jacquard-loom-poster.jpg","cta_label":"Khám phá lưu trữ","cta_href":"/san-pham"}},{"id":"lm-lookbook","type":"lookbook","visible":true,"variant":"framed-gallery","settings":{"surface":"surface","padding":"generous","columns":2},"props":{"title":"Bộ ảnh Maison","subtitle":"Chi tiết mắt dệt, cổ áo đứng dáng và ánh sắc trầm ấm.","cta_label":"Xem tuyển chọn","cta_href":"/san-pham"},"blocks":[{"id":"lm-lb1","type":"image","props":{"image_url":"/atmosphere/jacquard-loom-poster.jpg","alt":"Khung cửi dệt kim tinh xảo","caption":"Mắt dệt Jacquard \u0026 Rib 1:1","aspect":"landscape"}},{"id":"lm-lb2","type":"image","props":{"image_url":"/atmosphere/cotton-twill-slate.jpg","alt":"Bề mặt vải chéo màu đá","caption":"Độ rủ và kết cấu bề mặt","aspect":"landscape"}}]},{"id":"lm-manifesto","type":"text","visible":true,"variant":"split-quote","settings":{"surface":"bg","padding":"generous","align":"left"},"props":{"title":"Giá trị nằm ở điều không vội vã","body":"Chúng tôi giữ quy mô xưởng nhỏ để mọi chiếc áo đều đi qua bàn soi ánh sáng trước khi đóng hộp. Từ bo cổ, đường nối vai đến độ đàn hồi của gấu áo đều tuân thủ tiêu chuẩn khắt khe.","align":"left"},"blocks":[{"id":"lm-q1","type":"quote","props":{"body":"Sự sang trọng thực sự thể hiện qua cảm giác chạm tay và độ bền qua năm tháng.","author":"Đức Anh","role":"Nghệ nhân dệt kim"}}]},{"id":"lm-featured","type":"featured_products","visible":true,"variant":"editorial","settings":{"surface":"surface","padding":"generous","columns":2,"max_items":4},"props":{"title":"Tuyển phẩm giới hạn","subtitle":"Bốn thiết kế tiêu biểu của mùa hiện tại.","product_ids":[],"limit":4}},{"id":"lm-collection","type":"collection","visible":true,"variant":"gallery","settings":{"surface":"band","padding":"normal","columns":2},"props":{"title":"Dòng dệt kim \u0026 nỉ 320gsm","subtitle":"Giữ phom đứng cho tiết trời se lạnh và không gian điều hòa.","collection_slug":"maison-knitwear","category_slug":"ao-polo","image_url":"/atmosphere/cotton-twill-slate.jpg","limit":4}},{"id":"lm-policies","type":"policies","visible":true,"variant":"list","settings":{"surface":"bg","padding":"normal"},"props":{"title":"Đặc quyền khách hàng Maison","items":[{"heading":"Hộp quà lưu trữ cao cấp","detail":"Đóng gói trong hộp cứng kèm giấy lụa và thẻ chăm sóc riêng."},{"heading":"Đổi cỡ tận nơi trong 45 ngày","detail":"Dịch vụ nhận và giao lại riêng biệt không phát sinh chi phí."},{"heading":"Tư vấn 1–1 cùng chuyên viên","detail":"Hỗ trợ đo chọn kích cỡ và bảo quản sợi dệt kim lâu bền."}]}}],"pages":{"catalog":{"layout":"luxury-curated","columns":2,"show_filters":true,"show_search":false,"show_sku_matrix":false,"intro_title":"Bộ sưu tập tuyển chọn","intro_subtitle":"Khám phá từng thiết kế trong không gian trưng bày tinh giản."},"pdp":{"layout":"luxury-framed","gallery_style":"framed","show_vouchers":false,"show_sku_table":false,"show_story_band":true,"show_related":true},"cart":{"layout":"luxury-folio","show_vouchers":true,"show_addons":false,"trust_note":"Mỗi đơn hàng được đóng hộp thủ công và bảo vệ trọn vẹn khi vận chuyển."},"info":{"layout":"luxury-maison","show_factory_profile":true,"show_toc":false,"show_showcase":true}}}$cfg$::jsonb, TRUE, 6
) ON CONFLICT (id) DO NOTHING;

INSERT INTO site_templates (
    id, slug, name, category, archetype, description, preview_image_url, tags, config, is_active, sort_order
) VALUES (
    'one-page-launch', 'one-page-launch', 'Một Trang Ra Mắt', 'launch', 'one-page-launch', 'Bố cục tập trung chuyển đổi cho thương hiệu ít SKU hoặc đợt ra mắt sản phẩm chủ lực với điều hướng neo gọn và điểm nhấn giá trị rõ ràng.', '/banners/campaign-green-fiber.jpg', ARRAY['one-page', 'launch', 'hero-product', 'conversion']::text[], $cfg${"schema_version":2,"template_id":"one-page-launch","theme":{"bg_color":"#F8FAFC","surface_color":"#FFFFFF","text_color":"#0F172A","accent_color":"#4338CA","accent_text_color":"#FFFFFF","font_family":"be-vietnam-pro","logo_url":"/banners/campaign-everyday.jpg","banner_url":"/banners/campaign-green-fiber.jpg","brand_name":"Sản Phẩm Ra Mắt","tagline":"Một thiết kế chủ lực hoàn thiện đến từng chi tiết, sẵn sàng giao ngay","radius":"lg","density":"balanced"},"layout":{"archetype":"one-page-launch","header_style":"anchor-minimal","footer_style":"minimal-row","container_width":"standard","card_style":"minimal","show_announcement":true,"announcement_text":"Đợt mở bán đầu tiên • Ưu đãi đặt sớm kèm đổi size miễn phí 45 ngày","slots":{"search":true,"chat":true,"assistant":true}},"sections":[{"id":"op-hero","type":"hero","visible":true,"variant":"compact-launch","settings":{"surface":"bg","padding":"generous","align":"center"},"props":{"eyebrow":"PHIÊN BẢN RA MẮT 2026","title":"Chiếc áo duy nhất bạn muốn mặc mỗi ngày","subtitle":"Tối ưu độ thoáng, độ đứng phom và cảm giác mềm mại chỉ trong một dòng sản phẩm chủ lực.","image_url":"/banners/campaign-green-fiber.jpg","cta_label":"Đặt mua ngay","cta_href":"/san-pham"},"blocks":[{"id":"op-h-b1","type":"badge","props":{"label":"Mở bán giới hạn","tone":"accent"}},{"id":"op-h-c1","type":"cta","props":{"label":"Xem thông số","href":"/gioi-thieu","style":"secondary"}}]},{"id":"op-metrics","type":"metrics_strip","visible":true,"variant":"grid","settings":{"surface":"surface","padding":"normal","columns":3},"props":{"title":"Ba con số tạo nên khác biệt","subtitle":"Tập trung toàn bộ nguồn lực vào chất lượng cốt lõi."},"blocks":[{"id":"op-m1","type":"stat","props":{"value":"40+","label":"Chu kỳ giặt giữ phom","note":"Kiểm định co rút \u003c 2%"}},{"id":"op-m2","type":"stat","props":{"value":"4.9/5","label":"Mức độ hài lòng","note":"Từ khách hàng đặt sớm"}},{"id":"op-m3","type":"stat","props":{"value":"24 giờ","label":"Xử lý xuất kho","note":"Giao nhanh toàn quốc"}}]},{"id":"op-features","type":"text","visible":true,"variant":"manifesto","settings":{"surface":"band","padding":"normal","align":"left"},"props":{"title":"Vì sao chúng tôi chỉ làm 3 thiết kế cốt lõi?","body":"Thay vì ra mắt hàng trăm mẫu mã mỗi mùa, toàn bộ thời gian thiết kế và kiểm định được dồn cho những món đồ mặc nhiều nhất trong tuần.","align":"left"},"blocks":[{"id":"op-f1","type":"feature","props":{"title":"Cổ áo chống bai giãn","detail":"Dệt bo rib mật độ cao giữ đường cổ phẳng phiu cả ngày.","tag":"Chi tiết 01"}},{"id":"op-f2","type":"feature","props":{"title":"Thân áo thoáng nhẹ","detail":"Bề mặt mịn không bám da khi di chuyển ngoài trời.","tag":"Chi tiết 02"}},{"id":"op-f3","type":"feature","props":{"title":"Phom dáng dễ chọn cỡ","detail":"Bảng size chuẩn dáng người Việt từ S đến XXL.","tag":"Chi tiết 03"}}]},{"id":"op-featured","type":"featured_products","visible":true,"variant":"spotlight","settings":{"surface":"surface","padding":"normal","columns":3,"max_items":3},"props":{"title":"Chọn phiên bản của bạn","subtitle":"Đặt trực tiếp ngay hôm nay để nhận ưu đãi đợt mở bán.","product_ids":[],"limit":3}},{"id":"op-testimonials","type":"testimonials","visible":true,"variant":"single-feature","settings":{"surface":"bg","padding":"normal"},"props":{"title":"Phản hồi đầu tiên","subtitle":"Trải nghiệm từ nhóm khách thử nghiệm trước ngày mở bán."},"blocks":[{"id":"op-q1","type":"quote","props":{"body":"Nhận áo xong mình đặt thêm luôn hai màu còn lại vì mặc cực kỳ nhẹ và đứng dáng.","author":"Thanh Tùng","role":"Kỹ sư phần mềm, TP.HCM"}}]},{"id":"op-vouchers","type":"voucher_strip","visible":true,"variant":"tickets","settings":{"surface":"accent-soft","padding":"compact"},"props":{"title":"Ưu đãi đặt sớm","subtitle":"Số lượng có hạn cho đợt ra mắt đầu tiên.","limit":3}},{"id":"op-policies","type":"policies","visible":true,"variant":"cards","settings":{"surface":"surface","padding":"compact","columns":3},"props":{"title":"Bảo chứng trải nghiệm","items":[{"heading":"Dùng thử an tâm 45 ngày","detail":"Không vừa ý được đổi size hoặc hoàn tiền minh bạch."},{"heading":"Thanh toán linh hoạt","detail":"Hỗ trợ VietQR xác nhận tức thì và COD đồng kiểm."},{"heading":"Hỗ trợ trực tiếp","detail":"Trò chuyện ngay với đội ngũ phát triển sản phẩm."}]}}],"pages":{"catalog":{"layout":"single-strip","columns":3,"show_filters":false,"show_search":false,"show_sku_matrix":false,"intro_title":"Dòng sản phẩm ra mắt","intro_subtitle":"Tất cả phiên bản màu sắc và kích cỡ trong đợt mở bán hiện tại."},"pdp":{"layout":"one-page-drawer","gallery_style":"stacked","show_vouchers":true,"show_sku_table":false,"show_story_band":true,"show_related":false},"cart":{"layout":"express-bar","show_vouchers":true,"show_addons":true,"trust_note":"Thanh toán một bước gọn gàng, miễn phí đổi cỡ tận nơi."},"info":{"layout":"compact-faq","show_factory_profile":true,"show_toc":false,"show_showcase":false}}}$cfg$::jsonb, TRUE, 7
) ON CONFLICT (id) DO NOTHING;

